<script setup>
import {ref,onMounted,computed} from 'vue';import {api} from '../store';const registros=ref([]),historial=ref([]),ultimo=ref(null),error=ref('');onMounted(async()=>{try{[registros.value,historial.value]=await Promise.all([api('/registros'),api('/historial')]);if(historial.value.length)ultimo.value=(await api('/historial/'+historial.value[0].id)).resultado}catch(e){error.value=e.message}});const estudiantes=computed(()=>new Set(registros.value.map(r=>r.estudiante)).size);
</script><template><div class="page-heading"><div><div class="eyebrow">PANEL DOCENTE</div><h2>Seguimiento académico</h2><p>Identifica necesidades de acompañamiento y analiza el rendimiento del grupo.</p></div><RouterLink to="/analisis" class="btn btn-primary"><i class="bi bi-graph-up"></i> Nuevo análisis</RouterLink></div><div v-if="error" class="alert alert-danger">{{error}}</div><div class="row g-3 mb-4"><div v-for="m in [['Estudiantes registrados',estudiantes],['Calificaciones',registros.length],['Análisis guardados',historial.length],['Riesgo alto (último análisis)',ultimo?.riesgos.Alto??'—']]" :key="m[0]" class="col-6 col-xl-3"><div class="card metric"><span>{{m[0]}}</span><strong>{{m[1]}}</strong></div></div></div><div class="row g-3"><div class="col-lg-7"><div class="card p-4 h-100"><h5>Último diagnóstico</h5><template v-if="ultimo"><p>Promedio: <strong>{{ultimo.promedio}}</strong> · Aprobación: {{ultimo.aprobacion}}%</p><div v-for="n in ['Alto','Medio','Bajo']" :key="n" class="mb-3"><div class="d-flex justify-content-between"><span>Riesgo {{n.toLowerCase()}}</span><strong>{{ultimo.riesgos[n]}}</strong></div><div class="progress"><div :class="['progress-bar',n==='Alto'?'bg-danger':n==='Medio'?'bg-warning':'bg-success']" :style="{width:ultimo.riesgos[n]/ultimo.estudiantes*100+'%'}"></div></div></div><RouterLink to="/historial" class="subtle-link">Consultar historial</RouterLink></template><p v-else class="empty-state">Realiza tu primer análisis para visualizar el diagnóstico.</p></div></div><div class="col-lg-5"><div class="card p-4 h-100"><h5>Acciones rápidas</h5><RouterLink to="/registros" class="btn btn-outline-primary mb-2">Registrar calificaciones</RouterLink><RouterLink to="/analisis" class="btn btn-outline-primary mb-2">Importar CSV y analizar</RouterLink><RouterLink to="/historial" class="btn btn-outline-primary">Ver reportes anteriores</RouterLink><p class="text-secondary small mt-3">Las alertas de riesgo son orientativas y no reemplazan el criterio docente.</p></div></div></div></template>